import{_ as r,C as c,o,c as s,j as t,a as i,b as d,w as n,E as l,a1 as p,a0 as g}from"./chunks/framework.DYS8d9tm.js";const _=JSON.parse('{"title":"📱 Mobile Native Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"technical/mobile/native_architecture.md","filePath":"technical/mobile/native_architecture.md"}'),u={name:"technical/mobile/native_architecture.md"};function m(h,e,f,S,A,y){const a=c("Mermaid");return o(),s("div",null,[e[1]||(e[1]=t("h1",{id:"📱-mobile-native-architecture",tabindex:"-1"},[i("📱 Mobile Native Architecture "),t("a",{class:"header-anchor",href:"#📱-mobile-native-architecture","aria-label":'Permalink to "📱 Mobile Native Architecture"'},"​")],-1)),e[2]||(e[2]=t("p",null,"WealthFam Mobile (Android) is the primary real-time ingestion sensor for the ecosystem. It is engineered to capture, hash, geolocate, and transmit financial alerts with high reliability, minimal battery impact, and strict adherence to modern Android OS background restrictions.",-1)),e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"⚡-native-ingestion-lifecycle",tabindex:"-1"},[i("⚡ Native Ingestion Lifecycle "),t("a",{class:"header-anchor",href:"#⚡-native-ingestion-lifecycle","aria-label":'Permalink to "⚡ Native Ingestion Lifecycle"'},"​")],-1)),e[5]||(e[5]=t("p",null,"The mobile app implements a decoupled, process-safe architecture combining a high-priority native BroadcastReceiver, durable filesystem queues, and a foreground data-sync service.",-1)),(o(),d(p,null,{default:n(()=>[l(a,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20%22Android%20OS%20Layer%22%0A%20%20%20%20%20%20%20%20INTENT%5B%22Telephony.SMS_RECEIVED%20(Priority%20999)%22%5D%0A%20%20%20%20%20%20%20%20GPS%5B%22FusedLocationProvider%20%2F%20GPS%20%2F%20Network%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Native%20Android%20Layer%20(Kotlin)%22%0A%20%20%20%20%20%20%20%20RECV%5B%22SmsReceiver.kt%22%5D%0A%20%20%20%20%20%20%20%20OTP_FILTER%7B%22Smart%20Pure%20OTP%20Filter%22%7D%0A%20%20%20%20%20%20%20%20LOC_PARSER%5B%22extractDouble()%20%2B%20LocationManager%22%5D%0A%20%20%20%20%20%20%20%20RELAY_DIR%5B%22files%2Fsms_relay%2Frelay_*.json%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Dart%20Background%20Layer%22%0A%20%20%20%20%20%20%20%20FG_TASK%5B%22Foreground%20Task%20Isolate%20(SyncTaskHandler)%22%5D%0A%20%20%20%20%20%20%20%20DEDUP%5B%22SHA-256%20Deduplication%20(Hour%20Precision)%22%5D%0A%20%20%20%20%20%20%20%20JOURNAL%5B%22synced_hashes.db%20%2B%20SharedPreferences%22%5D%0A%20%20%20%20%20%20%20%20QUEUE%5B%22sms_offline_queue%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%22Backend%20Ingestion%22%0A%20%20%20%20%20%20%20%20API%5B%22FastAPI%20%2Fapi%2Fv1%2Fingestion%2Fsms%22%5D%0A%20%20%20%20%20%20%20%20PARSER%5B%22External%20Transaction%20Parser%22%5D%0A%20%20%20%20%20%20%20%20DB%5B%22PostgreSQL%20(Transaction%20%2B%20Geolocation)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20INTENT%20--%3E%20RECV%0A%20%20%20%20GPS%20-.-%3E%20LOC_PARSER%0A%20%20%20%20RECV%20--%3E%20OTP_FILTER%0A%20%20%20%20OTP_FILTER%20--%20%22Non-Financial%20OTP%22%20--%3E%20DISCARD%5B%22Discard%20on-device%22%5D%0A%20%20%20%20OTP_FILTER%20--%20%22Financial%20%2F%20Transactional%22%20--%3E%20LOC_PARSER%0A%20%20%20%20LOC_PARSER%20--%3E%20RELAY_DIR%0A%20%20%20%20RELAY_DIR%20--%3E%20FG_TASK%0A%20%20%20%20FG_TASK%20--%3E%20DEDUP%0A%20%20%20%20DEDUP%20--%3E%20JOURNAL%0A%20%20%20%20FG_TASK%20--%3E%7COnline%7C%20API%0A%20%20%20%20FG_TASK%20--%3E%7COffline%7C%20QUEUE%0A%20%20%20%20API%20--%3E%20PARSER%0A%20%20%20%20PARSER%20--%3E%20DB%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=g('<hr><h2 id="🛡️-secure-permissions-hardware-access" tabindex="-1">🛡️ Secure Permissions &amp; Hardware Access <a class="header-anchor" href="#🛡️-secure-permissions-hardware-access" aria-label="Permalink to &quot;🛡️ Secure Permissions &amp; Hardware Access&quot;">​</a></h2><p>The app requires specific permissions configured in <code>AndroidManifest.xml</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Permission</th><th style="text-align:left;">Scope</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>RECEIVE_SMS</code></td><td style="text-align:left;"><code>android.permission.RECEIVE_SMS</code></td><td style="text-align:left;">High-priority real-time broadcast receiver (<code>SmsReceiver.kt</code>).</td></tr><tr><td style="text-align:left;"><code>READ_SMS</code></td><td style="text-align:left;"><code>android.permission.READ_SMS</code></td><td style="text-align:left;">Historical inbox reconciliation, deep search, and missed SMS import.</td></tr><tr><td style="text-align:left;"><code>ACCESS_FINE_LOCATION</code></td><td style="text-align:left;"><code>android.permission.ACCESS_FINE_LOCATION</code></td><td style="text-align:left;">High-accuracy GPS tagging for point-of-sale financial alerts.</td></tr><tr><td style="text-align:left;"><code>ACCESS_COARSE_LOCATION</code></td><td style="text-align:left;"><code>android.permission.ACCESS_COARSE_LOCATION</code></td><td style="text-align:left;">Low-power cell/WiFi triangulation for indoor transaction capture.</td></tr><tr><td style="text-align:left;"><code>FOREGROUND_SERVICE_DATA_SYNC</code></td><td style="text-align:left;"><code>android.permission.FOREGROUND_SERVICE_DATA_SYNC</code></td><td style="text-align:left;">Android 14+ compliant foreground service type for network sync.</td></tr><tr><td style="text-align:left;"><code>WAKE_LOCK</code></td><td style="text-align:left;"><code>android.permission.WAKE_LOCK</code></td><td style="text-align:left;">Ensures the atomic file-write completes if the device is in doze mode.</td></tr></tbody></table><hr><h2 id="🧭-location-capture-engine" tabindex="-1">🧭 Location Capture Engine <a class="header-anchor" href="#🧭-location-capture-engine" aria-label="Permalink to &quot;🧭 Location Capture Engine&quot;">​</a></h2><p>To ensure transaction payloads include geolocation coordinates without stalling the native receiver:</p><ol><li><strong>Hardware Provider Cascade</strong>: <ul><li>Queries <code>LocationManager.FUSED_PROVIDER</code> on Android 12+ (API 31+).</li><li>Falls back to <code>NETWORK_PROVIDER</code>, <code>PASSIVE_PROVIDER</code>, and <code>GPS_PROVIDER</code>.</li></ul></li><li><strong>Flutter SharedPreferences Decoding</strong>: <ul><li>Reads <code>flutter.cached_gps_lat</code> and <code>flutter.cached_gps_lng</code>.</li><li>Strips Flutter&#39;s Android double encoding prefix (<code>VGhpcyBpcyB0aGUgcHJlZml4IGZvciBEb3VibGUu</code>).</li><li>Supports explicit string double keys (<code>cached_gps_lat_str</code>, <code>cached_gps_lng_str</code>).</li></ul></li><li><strong>Flutter Startup Warm-Up</strong>: <ul><li><code>SmsService.init()</code> warms up the location hardware on app launch to seed the cache before incoming SMS arrive.</li></ul></li></ol><hr><h2 id="🔒-security-resilience-principles" tabindex="-1">🔒 Security &amp; Resilience Principles <a class="header-anchor" href="#🔒-security-resilience-principles" aria-label="Permalink to &quot;🔒 Security &amp; Resilience Principles&quot;">​</a></h2><ol><li><strong>Decoupled File Relay</strong>: Incoming SMS are written immediately to <code>context.filesDir/sms_relay/</code>. This eliminates crashes from Android 12+ <code>ForegroundServiceStartNotAllowedException</code> when the app is in the background.</li><li><strong>Deterministic Cryptographic Hashing</strong>: Messages are deduplicated using <code>SHA-256(cleanAddress-YYYYMMDDHH-cleanBody)</code>. Hour-level timestamp normalization eliminates timestamp jitter across cellular carriers.</li><li><strong>Store-and-Forward Offline Resilience</strong>: Messages that fail network transmission are preserved in <code>sms_offline_queue</code> with their original timestamp and GPS telemetry, automatically flushing when connectivity is regained.</li><li><strong>Debug Payloads &amp; Verification</strong>: The built-in <code>SmsDebugLogsScreen</code> provides real-time visibility into outgoing backend payloads, HTTP response codes, and GPS telemetry badges (🟢 <code>📍 lat, lng</code> vs 🟠 <code>⚠️ No GPS</code>).</li></ol><hr><h2 id="🏛️-accounts-cross-account-transfers-architecture" tabindex="-1">🏛️ Accounts &amp; Cross-Account Transfers Architecture <a class="header-anchor" href="#🏛️-accounts-cross-account-transfers-architecture" aria-label="Permalink to &quot;🏛️ Accounts &amp; Cross-Account Transfers Architecture&quot;">​</a></h2><p>The mobile app includes specialized views, data models, and services mirroring the enterprise Web app:</p><ol><li><p><strong>Multi-Instrument Screens</strong>:</p><ul><li><code>DepositsScreen</code> (<code>lib/modules/accounts/screens/deposits_screen.dart</code>): Fixed Deposits &amp; Recurring Deposits listing with dynamic accrued interest, maturity progress bars, and KPI banner.</li><li><code>ProvidentFundsScreen</code> (<code>lib/modules/accounts/screens/provident_funds_screen.dart</code>): Tripartite EPF/PPF/NPS views with annual statutory ₹1.5L contribution meter.</li><li><code>AccountDetailScreen</code> (<code>lib/modules/accounts/screens/account_detail_screen.dart</code>): Rich telemetry cards for FDs (compounding frequency, tenure, maturity value) and PFs (employee/employer/pension split).</li><li><code>AccountsScreen</code> &amp; App Drawer: Direct navigation to Credit Cards with cycle dues and utilization health.</li></ul></li><li><p><strong>Transfers Hub (<code>transfers_hub_screen.dart</code>)</strong>:</p><ul><li><strong>Batch Pairing</strong>: 1-click &quot;Approve All High-Confidence Pairs&quot; banner using <code>/api/v1/mobile/transfers/batch-pair</code>.</li><li><strong>1-Click Counterpart Leg Generation</strong>: Bottom sheet dialog enabling users to auto-generate the missing credit leg on destination accounts with editable credited amounts to accommodate discounts and cashback.</li><li><strong>Unpair &amp; Rollback</strong>: Safe unlinking via <code>/api/v1/mobile/transfers/unpair/{id}</code> with automatic statement balance and card dues restoration.</li></ul></li><li><p><strong>Telemetry, Real-Time WebSockets &amp; Presentation Parity</strong>:</p><ul><li><strong>RFC-Compliant WebSocket Authentication (<code>socket_service.dart</code>)</strong>: Real-time alerts connect via <code>IOWebSocketChannel.connect(Uri.parse(wsUrl), protocols: [&#39;wealthfam-auth&#39;, token])</code>, negotiating <code>Sec-WebSocket-Protocol</code> without leaking JWTs in URL query strings.</li><li><strong>GPS Tag Serialization</strong>: <code>RecentTransaction</code> schema explicitly includes <code>latitude</code> and <code>longitude</code> fields, ensuring that coordinates captured during SMS and bank sync are delivered to mobile transaction sheets.</li><li><strong>Active Expense Groups &amp; Refund Netting</strong>: <code>ExpenseGroupPickerSheet</code> enforces active state filtering (<code>is_active != false</code>), while <code>ExpenseGroupDetailsScreen</code>, <code>ExpenseGroupBreakdownTab</code>, <code>ExpenseGroupInsightsTab</code>, and <code>ManageGroupTransactionsScreen</code> exclude transfers/hidden items (<code>exclude_from_reports == False &amp;&amp; is_transfer == False</code>) and net positive refunds against group spend.</li><li><strong>Relational Category &amp; Spending Metric Alignment</strong>: <code>TransactionModel</code> and <code>RecentTransaction</code> propagate <code>categoryId</code> and <code>categoryType</code> (<code>&#39;income&#39;</code>, <code>&#39;expense&#39;</code>, <code>&#39;investment&#39;</code>, <code>&#39;transfer&#39;</code>). <code>TransactionsScreen</code>, <code>MerchantDetailScreen</code>, and <code>AnalyticsMerchantsTab</code> strictly classify operating income (<code>categoryType == &#39;income&#39;</code>), net living expense refunds (<code>categoryType == &#39;expense&#39;</code>), and isolate investment redemptions from operating income.</li></ul></li><li><p><strong>Touch Target Polish &amp; Accessibility (WCAG 2.1 / Material 3 Compliance)</strong>:</p><ul><li><strong>Global Tap Target Standardization (<code>app_theme.dart</code>)</strong>: Enforces minimum $48 \\times 48\\text{ dp}$ primary targets via <code>iconButtonTheme</code> (<code>tapTargetSize: MaterialTapTargetSize.padded</code>), <code>elevatedButtonTheme</code> (<code>minimumSize: Size(0, 48)</code>), <code>textButtonTheme</code>, and <code>outlinedButtonTheme</code>.</li><li><strong>Inline Micro-Target Expansion</strong>: Replaced bare $14\\text{ dp}$ gesture detectors with $\\ge 36 \\times 36\\text{ dp}$ <code>InkResponse</code> targets for attachment icons in <code>TransactionListTile</code> and active filter chip dismiss icons in <code>ActiveFilterChips</code>. Standardized sheet close buttons across all pickers to $44 \\times 44\\text{ dp}$.</li></ul></li><li><p><strong>Attention Hub &amp; Persistent Notification Activity Stream</strong>:</p><ul><li><strong>Two-Tab Architecture (<code>attention_hub_screen.dart</code>)</strong>: Tab 1 consolidates real-time financial action items (<code>AttentionItemModel</code>), while Tab 2 displays the historical notification activity stream.</li><li><strong>Database Alert Persistence</strong>: Hydrates the Activity stream using <code>GET /api/v1/mobile/alerts/history</code> on startup and refresh, merging real-time WebSocket frames, rendering unread indicators, and syncing read status via <code>POST /api/v1/mobile/alerts/{alert_id}/read</code>.</li><li><strong>Notification Deduplication</strong>: Eliminated the redundant background HTTP polling loop in <code>foreground_task_handler.dart</code> to prevent duplicate push alerts while WebSocket is active.</li></ul></li><li><p><strong>3-Way Transaction Classification &amp; Scoped Category Picker</strong>:</p><ul><li><strong>Segmented Entry Selector (<code>add_transaction_screen.dart</code>)</strong>: Manual transaction entry allows 3-way classification: <code>Expense</code> (outflow), <code>Income</code> (inflow), and <code>Investment</code> (outflow).</li><li><strong>Scoped Category Picker Tabs (<code>searchable_category_picker.dart</code>)</strong>: Displays type filter chips (<code>All</code>, <code>Expense</code>, <code>Income</code>, <code>Investment</code>) and automatically scopes to the active entry mode with instant switching.</li><li><strong>Unified Savings Rate Engine</strong>: Synchronized with backend formula: $$\\text{Savings Rate} = \\frac{\\text{Operating Income} - \\text{Operating Expenses}}{\\text{Operating Income}} \\times 100$$ strictly excluding investment outflows from operational living expenses.</li></ul></li><li><p><strong>Native Document Scanner with Straightening</strong>:</p><ul><li><strong>Google ML Kit Document Scanner (<code>DocumentScannerService</code>)</strong>: Configured with <code>ScannerMode.full</code> for on-device automatic boundary detection, perspective transformation / straightening, shadow removal, and contrast enhancement, with graceful camera photo fallback.</li><li><strong>Unified Document Capture Sheet (<code>document_capture_sheet.dart</code>)</strong>: Reusable bottom sheet offering AI document scan, standard camera snapshot, and device file/PDF picking, integrated directly into transaction evidence linking and Vault uploads.</li></ul></li><li><p><strong>Visual Intelligence &amp; 6-Month Trend Sparklines</strong>:</p><ul><li><strong>CustomPainter Sparkline (<code>sparkline_widget.dart</code>)</strong>: Smooth cubic Bézier curve renderer with semi-transparent area gradient fill and final-point indicator dot.</li><li><strong>Dual Card Sparklines (<code>dashboard_screen.dart</code>)</strong>: Displays 6-month historical investment trends (Teal) on the Mutual Funds portfolio card and 6-month spending trends (Indigo) on the recurring spending card, powered by <code>/api/v1/mobile/dashboard/trends</code> historical month aggregation.</li></ul></li></ol><hr><div align="center"> *Real-time Ingestion · Native Performance · Offline Sovereignty* </div>',17))])}const E=r(u,[["render",m]]);export{_ as __pageData,E as default};
